import{_ as o,o as e,c as s,l as n,t as r,N as a}from"./chunks/framework.Gjrf2Eoj.js";const f=JSON.parse('{"title":"ipcs | x-cmd man (ip man1) | show information on IPC facilities","titleTemplate":false,"description":"x-cmd man (ip man1 Manual Page) | ipcs - show information on IPC facilities","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipcs | x-cmd man (ip man1) | show information on IPC facilities"}],["meta",{"name":"og:description","content":"x-cmd man (ip man1 Manual Page) | ipcs - show information on IPC facilities"}]]},"headers":[],"params":{"isMan":true,"man":"ipcs","category":"ip man1","desc":"show information on IPC facilities"},"relativePath":"ip/man1/ipcs.md","filePath":"ip/man1/ipcs.md"}'),i={name:"ip/man1/ipcs.md"},l={class:"visually-hidden"},p=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ipcs - show information on IPC facilities</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ipcs</strong> [options]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>ipcs</strong> shows information on System V inter-process communication facilities. By default it shows information about all three resources: shared memory segments, message queues, and semaphore arrays.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-i</strong>, <strong>--id</strong> <em>id</em></p><blockquote><p>Show full details on just the one resource element identified by <em>id</em>. This option needs to be combined with one of the three resource options: <strong>-m</strong>, <strong>-q</strong> or <strong>-s</strong>.</p></blockquote><p><strong>-h</strong>, <strong>--help</strong></p><blockquote><p>Display help text and exit.</p></blockquote><p><strong>-V</strong>, <strong>--version</strong></p><blockquote><p>Print version and exit.</p></blockquote><h3 id="resource-options" tabindex="-1">Resource options <a class="header-anchor" href="#resource-options" aria-label="Permalink to &quot;Resource options&quot;">​</a></h3><p><strong>-m</strong>, <strong>--shmems</strong></p><blockquote><p>Write information about active shared memory segments.</p></blockquote><p><strong>-q</strong>, <strong>--queues</strong></p><blockquote><p>Write information about active message queues.</p></blockquote><p><strong>-s</strong>, <strong>--semaphores</strong></p><blockquote><p>Write information about active semaphore sets.</p></blockquote><p><strong>-a</strong>, <strong>--all</strong></p><blockquote><p>Write information about all three resources (default).</p></blockquote><h3 id="output-formats" tabindex="-1">Output formats <a class="header-anchor" href="#output-formats" aria-label="Permalink to &quot;Output formats&quot;">​</a></h3><p>Of these options only one takes effect: the last one specified.</p><p><strong>-c</strong>, <strong>--creator</strong></p><blockquote><p>Show creator and owner.</p></blockquote><p><strong>-l</strong>, <strong>--limits</strong></p><blockquote><p>Show resource limits.</p></blockquote><p><strong>-p</strong>, <strong>--pid</strong></p><blockquote><p>Show PIDs of creator and last operator.</p></blockquote><p><strong>-t</strong>, <strong>--time</strong></p><blockquote><p>Write time information. The time of the last control operation that changed the access permissions for all facilities, the time of the last <strong>msgsnd</strong>(2) and <strong>msgrcv</strong>(2) operations on message queues, the time of the last <strong>shmat</strong>(2) and <strong>shmdt</strong>(2) operations on shared memory, and the time of the last <strong>semop</strong>(2) operation on semaphores.</p></blockquote><p><strong>-u</strong>, <strong>--summary</strong></p><blockquote><p>Show status summary.</p></blockquote><h3 id="representation" tabindex="-1">Representation <a class="header-anchor" href="#representation" aria-label="Permalink to &quot;Representation&quot;">​</a></h3><p>These affect only the <strong>-l</strong> (<strong>--limits</strong>) option.</p><p><strong>-b</strong>, <strong>--bytes</strong></p><blockquote><p>Print the sizes in bytes rather than in a human-readable format.</p><p>By default, the unit, sizes are expressed in, is byte, and unit prefixes are in power of 2^10 (1024). Abbreviations of symbols are exhibited truncated in order to reach a better readability, by exhibiting alone the first letter of them; examples: &quot;1 KiB&quot; and &quot;1 MiB&quot; are respectively exhibited as &quot;1 K&quot; and &quot;1 M&quot;, then omitting on purpose the mention &quot;iB&quot;, which is part of these abbreviations.</p></blockquote><p><strong>--human</strong></p><blockquote><p>Print sizes in human-readable format.</p></blockquote><h2 id="conforming-to" tabindex="-1">CONFORMING TO <a class="header-anchor" href="#conforming-to" aria-label="Permalink to &quot;CONFORMING TO&quot;">​</a></h2><p>The Linux <strong>ipcs</strong> utility is not fully compatible to the POSIX <strong>ipcs</strong> utility. The Linux version does not support the POSIX <strong>-a</strong>, <strong>-b</strong> and <strong>-o</strong> options, but does support the <strong>-l</strong> and <strong>-u</strong> options not defined by POSIX. A portable application shall not use the <strong>-a</strong>, <strong>-b</strong>, <strong>-o</strong>, <strong>-l</strong>, and <strong>-u</strong> options.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>The current implementation of <strong>ipcs</strong> obtains information about available IPC resources by parsing the files in <em>/proc/sysvipc</em>. Before util-linux version v2.23, an alternate mechanism was used: the <strong>IPC_STAT</strong> command of <strong>msgctl</strong>(2), <strong>semctl</strong>(2), and <strong>shmctl</strong>(2). This mechanism is also used in later util-linux versions in the case where <em>/proc</em> is unavailable. A limitation of the <strong>IPC_STAT</strong> mechanism is that it can only be used to retrieve information about IPC resources for which the user has read permission.</p><h2 id="authors" tabindex="-1">AUTHORS <a class="header-anchor" href="#authors" aria-label="Permalink to &quot;AUTHORS&quot;">​</a></h2><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>ipcmk</strong>(1), <strong>ipcrm</strong>(1), <strong>msgrcv</strong>(2), <strong>msgsnd</strong>(2), <strong>semget</strong>(2), <strong>semop</strong>(2), <strong>shmat</strong>(2), <strong>shmdt</strong>(2), <strong>shmget</strong>(2), <strong>sysvipc</strong>(7)</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>For bug reports, use the issue tracker at &lt;<a href="https://github.com/util-linux/util-linux/issues%5C" target="_blank" rel="noreferrer">https://github.com/util-linux/util-linux/issues\\</a>&gt;.</p><h2 id="availability" tabindex="-1">AVAILABILITY <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;AVAILABILITY&quot;">​</a></h2><p>The <strong>ipcs</strong> command is part of the util-linux package which can be downloaded from <em>Linux Kernel Archive</em> &lt;<a href="https://www.kernel.org/pub/linux/utils/util-linux/%5C" target="_blank" rel="noreferrer">https://www.kernel.org/pub/linux/utils/util-linux/\\</a>&gt;.</p>',51);function h(t,u,g,c,m,d){return e(),s("div",null,[n("h1",l,r(t.$params.man),1),p])}const q=o(i,[["render",h]]);export{f as __pageData,q as default};
